import{_ as r,a0 as i,w as u,s,I as o,x as e,a1 as n,A as p,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"不是程序员？那就找到自己的定位 | LCTT x X-CMD","titleTemplate":false,"description":"不是程序员？那就找到自己的定位 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不是程序员？那就找到自己的定位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不是程序员？那就找到自己的定位 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210218 Not an engineer- Find out where you belong","title":"不是程序员？那就找到自己的定位","tag":"202105","desc":""},"relativePath":"202105/20210218 Not an engineer- Find out where you belong.md","filePath":"[post].md"}'),d={name:"202105/20210218 Not an engineer- Find out where you belong.md"};function m(b,t,f,k,T,g){const l=i("Link");return u(),s("div",null,[t[23]||(t[23]=o("h1",{id:"不是程序员-那就找到自己的定位",tabindex:"-1"},[e("不是程序员？那就找到自己的定位 "),o("a",{class:"header-anchor",href:"#不是程序员-那就找到自己的定位","aria-label":"Permalink to “不是程序员？那就找到自己的定位”"},"​")],-1)),t[24]||(t[24]=o("blockquote",null,[o("p",null,"无论你是已经工作了几十年的还是刚开始从业的非工程型技术人，此建议都可以帮助你确定你的位置归属。")],-1)),t[25]||(t[25]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/31/192647jl354n1jezx1ea1c.jpg",alt:""})],-1)),o("p",null,[t[2]||(t[2]=e("在 ",-1)),n(l,{href:"https://linux.cn/article-13168-1.html"},{default:p(()=>[...t[0]||(t[0]=[e("本系列第一篇文章",-1)])]),_:1}),t[3]||(t[3]=e(" 中 ，我解释了将人员和角色分为“技术”或“非技术”类别的问题。在 ",-1)),n(l,{href:"https://linux.cn/article-13178-1.html"},{default:p(()=>[...t[1]||(t[1]=[e("第二篇文章",-1)])]),_:1}),t[4]||(t[4]=e(" 中，我为不写代码的人分享了一些技术岗位角色。这一次，我将把这次探索总结为——“技术或非技术意味着什么”，并提供一些能够在职业发展上帮到你的建议。",-1))]),t[26]||(t[26]=a('<p>无论你是已经从事技术工作数十年，或是刚刚起步，还是正在寻求职业变更，请考虑本文中来自非技术人员但在技术角色方面取得成功的人士的建议。</p><blockquote><p>“不要把你的工作和身份捆绑起来 —— 把它们分开。”</p><p>—— Adam Gordon Bell，Earthly Technologies 开发者关系部</p></blockquote><p>转换角色，并不意味着你的技能会消失且你不再具有价值。如果你担任了新角色，则需要专注于该角色的关键技能。培养技能是需要时间的。花点时间，找出新职位的重要技能。</p><p>如果你管理工程师们，请鼓励他们提升技术技能的同时发展非工程技能，这些技能往往能比编程能力和技术技能对职业发展和成功产生更显著的变化。</p><h3 id="做你自己" tabindex="-1">做你自己 <a class="header-anchor" href="#做你自己" aria-label="Permalink to “做你自己”">​</a></h3><blockquote><p>“不要让其他人定义你是技术人员还是非技术人员。什么是技术人员，什么不是技术人员，以及这是否重要，是人们必须自己搞清楚的事情。”</p><p>—— Adam Gordon Bell</p></blockquote><blockquote><p>“永远不要用‘我不是技术人员’为开头进行对话。因为很可能让对方产生‘这点我需要提醒你’的想法，这在面试的时候可从来不会留下好印象，而且还有可能会让人觉得你对自己技能缺乏信心。”</p><p>—— Mary Thengvall，Camunda 开发者关系总监</p></blockquote><p>避免刻板成见；不是所有的工程师都喜欢《星球大战》或《星际迷航》。不是所有工程师都穿连帽卫衣。工程师也可以和别人交流。</p><blockquote><p>“单单就你的行为举止，旁人就有很多关于技术或非技术方面的看法。在办公室工作的时候，我会穿裙子，因为只有这样我才能舒服一点。”</p><p>—— Shailvi Wakhlu，Strava 高级数据总监</p></blockquote><h3 id="了解你的价值" tabindex="-1">了解你的价值 <a class="header-anchor" href="#了解你的价值" aria-label="Permalink to “了解你的价值”">​</a></h3>',10)),o("p",null,[t[6]||(t[6]=e("正如我在第一篇文章中讨论的那样，被打上“非技术”的标签会导致 ",-1)),n(l,{href:"https://opensource.com/business/15/9/tips-avoiding-impostor-syndrome"},{default:p(()=>[...t[5]||(t[5]=[e("冒充者综合症",-1)])]),_:1}),t[7]||(t[7]=e("。承认自己的价值，不要在自己身上贴上“非技术”标签，因为它会限制你的收入潜力和职业发展。",-1))]),t[27]||(t[27]=a('<blockquote><p>“人们之所以把我重新包装成其他东西，是因为他们认为我和工程师的刻板印象不一样。我很高兴我没有听这些人的话，因为他们本质上是在告诉我，在我拥有的技能之外，去找一份低薪的工作。”</p><p>—— Shailvi Wakhlu</p></blockquote><blockquote><p>“年轻的或者女性技术人，特别是刚接触技术的女性，更容易患上冒名综合症，认为自己技术不够好。比如，‘哦，我只会前端。’，什​​么叫你<em>只会</em>前端？前端也很难的好吧。”</p><p>—— Liz Harris</p></blockquote><h3 id="寻找那些可以提升价值并帮到人们的地方" tabindex="-1">寻找那些可以提升价值并帮到人们的地方 <a class="header-anchor" href="#寻找那些可以提升价值并帮到人们的地方" aria-label="Permalink to “寻找那些可以提升价值并帮到人们的地方”">​</a></h3><p>你不需要创建 PR 就可以参与开源。</p><blockquote><p>“当有人想为开源项目做点贡献时，我总是对他说，‘不要想着，得是一个提交才行、得提一个 PR 才可以。’这就好像，‘不行。怎么才能为那个项目贡献点价值呢？’ 如果你没时间提交 PR，那你是不是提个议题并把要点写下来？”</p><p>—— Eddie Jaoude，Jaoude Studios 开源程序员</p></blockquote><h3 id="思维的多样性有助于事业成功" tabindex="-1">思维的多样性有助于事业成功 <a class="header-anchor" href="#思维的多样性有助于事业成功" aria-label="Permalink to “思维的多样性有助于事业成功”">​</a></h3><p>看看所有角色和人员的价值和贡献。不要根据头衔将人归到同能力的一组。</p><blockquote><p>“要认识到，所有人（包括自己在内），在任何时候，以及事情全貌的重要性。创造力这个事儿不应该由自我驱动。要知道，对于你所做的事情，你可以做的更好，也可以做的更糟。不要害怕寻求帮助，知道到我们在一起。”</p><p>—— Therese Eberhard，电影/广告和视频场景画师</p></blockquote><blockquote><p>“在我参加过的黑客马拉松中，我们都是技术人员，组建了一支四五个硬核程序员组成的强大团队，但我们输了。我不骗你，我们输了。在新冠疫情之前，我赢了前六次的黑客马拉松，而且当时团队中一半的人属于其他领域的专家。在我们赢过的比赛中，大多数人会认为团队一半人是非技术的，尽管我不喜欢这个术语，因为这像是给团队/项目贴金。我们之所以获胜，是因为我们对所构建的东西有很多不同的看法。”</p><p>—— Eddie Jaoude</p></blockquote><blockquote><p>“我们越能摆脱‘技术/非技术’、‘开发人员/非开发人员’的标签，并理解到一个连续统一的整体存在，我们就越能全力以赴地雇用到合适的人来做这项工作，只要不被你需要‘技术团队’的假设所困扰。”</p><p>—— Mary Thengvall</p></blockquote><p>我们的社区和团队越多样化，它们的包容性就越大。</p><blockquote><p>“老实说，无论是从社区角度还是从产品角度，我认为，总的来说，最重要的事情都是，我们应该确保我们建立的是一个包容性的社区，这不仅是为了我们的产品，也不仅是为了我们正在使用的技术，还为了整个人类社会，我想……我敢打赌，如果我们做到了这一点，那么作为人类，我们就比过去更进步了。”</p><p>—— Leon Stigter，Lightbend 高级产品经理</p></blockquote><p>如果你以非程序员的技术身份工作，你会给那些认为自己“非技术”的人（或被他人认为是“非技术”的人）提供什么建议？ 在评论中分享你的见解。</p><hr>',14)),o("p",null,[t[9]||(t[9]=e("via: ",-1)),n(l,{href:"https://opensource.com/article/21/2/advice-non-technical"},{default:p(()=>[...t[8]||(t[8]=[e("https://opensource.com/article/21/2/advice-non-technical",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=e("作者：",-1)),n(l,{href:"https://opensource.com/users/dawnparzych"},{default:p(()=>[...t[10]||(t[10]=[e("Dawn Parzych",-1)])]),_:1}),t[15]||(t[15]=e(" 选题：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 译者：",-1)),n(l,{href:"https://github.com/max27149"},{default:p(()=>[...t[12]||(t[12]=[e("max27149",-1)])]),_:1}),t[17]||(t[17]=e(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[20]||(t[20]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[19]||(t[19]=[e("Linux中国",-1)])]),_:1}),t[22]||(t[22]=e(" 荣誉推出",-1))])])}const C=r(d,[["render",m]]);export{q as __pageData,C as default};
